import json
import os
import re
from datetime import datetime, timezone
import boto3

PROJECT = os.environ["PROJECT_NAME"]
OPERATOR_GROUP = "origin-operators"
codebuild = boto3.client("codebuild")

def reply(status, payload):
    return {
        "statusCode": status,
        "headers": {
            "Content-Type": "application/json",
            "Cache-Control": "no-store",
            "X-Content-Type-Options": "nosniff"
        },
        "body": json.dumps(payload, separators=(",", ":"))
    }

def get_builds(limit=10):
    response = codebuild.list_builds_for_project(projectName=PROJECT, sortOrder="DESCENDING")
    ids = response.get("ids", [])[:limit]
    if not ids:
        return []
    result = codebuild.batch_get_builds(ids=ids)
    builds = result.get("builds", [])
    builds.sort(key=lambda item: item.get("startTime", datetime.min.replace(tzinfo=timezone.utc)), reverse=True)
    return builds

def clean(build):
    def dt(value):
        return value.astimezone(timezone.utc).isoformat() if value else None
    return {
        "id": build.get("id", "").rsplit(":", 1)[-1],
        "status": build.get("buildStatus", "UNKNOWN"),
        "phase": build.get("currentPhase"),
        "number": build.get("buildNumber"),
        "startedAt": dt(build.get("startTime")),
        "endedAt": dt(build.get("endTime")),
        "phases": [
            {"name": p.get("phaseType"), "status": p.get("phaseStatus")}
            for p in build.get("phases", [])
            if p.get("phaseType") in ("INSTALL", "BUILD", "POST_BUILD", "UPLOAD_ARTIFACTS")
        ]
    }

def handler(event, context):
    route = event.get("routeKey", "")
    try:
        if route == "GET /health":
            return reply(200, {"ok": True, "service": "origin-operations", "region": os.environ.get("AWS_REGION")})
        if route == "GET /status":
            builds = get_builds(12)
            return reply(200, {
                "service": "origin-operations",
                "project": PROJECT,
                "source": "aws-codebuild",
                "fetchedAt": datetime.now(timezone.utc).isoformat(),
                "builds": [clean(b) for b in builds],
                "startRequiresOperator": True
            })
        if route == "GET /logs":
            claims = (((event.get("requestContext") or {}).get("authorizer") or {}).get("jwt") or {}).get("claims") or {}
            groups = str(claims.get("cognito:groups") or "")
            if not re.search(r"(^|[^a-z0-9_-])origin-operators([^a-z0-9_-]|$)", groups):
                return reply(403, {"error": "Operator membership required for build logs."})
            build_id = str((event.get("queryStringParameters") or {}).get("id") or "")
            if not re.fullmatch(r"[a-f0-9-]{36}", build_id):
                return reply(400, {"error": "A valid build identifier is required."})
            matches = codebuild.batch_get_builds(ids=[PROJECT + ":" + build_id]).get("builds", [])
            if not matches or matches[0].get("projectName") != PROJECT:
                return reply(404, {"error": "Build not found."})
            log_info = matches[0].get("logs") or {}
            group_name = log_info.get("groupName")
            stream_name = log_info.get("streamName")
            if group_name != "/aws/codebuild/origin-public-ui-build-20261024" or not stream_name:
                return reply(404, {"error": "Build logs are not available."})
            cloudwatch = boto3.client("logs")
            events = cloudwatch.get_log_events(
                logGroupName=group_name, logStreamName=stream_name,
                limit=120, startFromHead=False
            ).get("events", [])
            return reply(200, {
                "build": build_id,
                "events": [
                    {"timestamp": item.get("timestamp"), "message": (item.get("message") or "")[:800]}
                    for item in events
                ]
            })
        if route == "POST /build":
            claims = (((event.get("requestContext") or {}).get("authorizer") or {}).get("jwt") or {}).get("claims") or {}
            groups = str(claims.get("cognito:groups") or "")
            if not re.search(r"(^|[^a-z0-9_-])origin-operators([^a-z0-9_-]|$)", groups):
                return reply(403, {"error": "Operator membership required for starting AWS builds."})
            builds = get_builds(6)
            if builds and builds[0].get("buildStatus") == "IN_PROGRESS":
                return reply(409, {"error": "A build is already in progress.", "build": clean(builds[0])})
            if builds and builds[0].get("startTime"):
                seconds = (datetime.now(timezone.utc) - builds[0]["startTime"]).total_seconds()
                if seconds < 180:
                    return reply(429, {"error": "Build cooldown is active. Try again after 3 minutes."})
            started = codebuild.start_build(projectName=PROJECT)
            return reply(202, {"accepted": True, "build": clean(started["build"])})
        return reply(404, {"error": "Unknown route."})
    except Exception:
        print("Origin operations request failed: route=" + route)
        return reply(503, {"error": "AWS operations temporarily unavailable."})
